mapper.select:
SELECT r.id, r.room_id, r.user_id, r.subject, r.attendee_count,
       r.contact_phone, r.remark, r.start_time, r.end_time,
       r.status, r.create_time, mr.name AS room_name
FROM meeting_room_reservation r
LEFT JOIN meeting_room mr ON mr.id = r.room_id AND mr.deleted = 0
WHERE r.deleted = 0
  AND r.user_id = #{userId}

      AND r.subject LIKE CONCAT('%', #{query.keyword}, '%')


      AND r.subject LIKE CONCAT('%', #{query.subject}, '%')


      AND r.status = #{query.status}


      AND r.start_time <= #{query.startTime} AND r.end_time >= #{query.startTime}


      AND r.start_time <= #{query.endTime} AND r.end_time >= #{query.endTime}

ORDER BY r.start_time DESC

SELECT r.id, r.room_id, r.user_id, r.subject, r.attendee_count,
       r.contact_phone, r.remark, r.start_time, r.end_time,
       r.status, r.create_time, mr.name AS room_name
FROM meeting_room_reservation r
LEFT JOIN meeting_room mr ON mr.id = r.room_id AND mr.deleted = 0
WHERE r.deleted = 0

      AND r.subject LIKE CONCAT('%', #{query.keyword}, '%')


      AND r.subject LIKE CONCAT('%', #{query.subject}, '%')


      AND r.room_id = #{query.roomId}


      AND r.user_id = #{query.userId}


      AND r.status = #{query.status}


      AND r.contact_phone LIKE CONCAT('%', #{query.contactPhone}, '%')


      AND r.start_time >= #{query.startTime}


      AND r.end_time <= #{query.endTime}

ORDER BY r.start_time DESC
